    <style>
        :root{--navy:#071528;--blue:#2774f5;--cyan:#57d9e8;--ink:#102039;--muted:#748198}*{box-sizing:border-box}body{margin:0;min-height:100vh;font-family:'DM Sans',sans-serif;color:var(--ink);background:#f5f7fb}.login-shell{min-height:100vh;display:grid;grid-template-columns:minmax(420px,1.03fr) minmax(420px,.97fr)}.login-visual{position:relative;overflow:hidden;display:flex;flex-direction:column;justify-content:space-between;padding:42px clamp(38px,6vw,92px);color:white;background:radial-gradient(ellipse at 70% 46%,rgba(22,118,255,.28),transparent 38%),linear-gradient(145deg,#071528 0%,#0c2342 58%,#092b48 100%)}.visual-grid{position:absolute;inset:0;opacity:.19;background-image:linear-gradient(rgba(125,186,255,.14) 1px,transparent 1px),linear-gradient(90deg,rgba(125,186,255,.14) 1px,transparent 1px);background-size:54px 54px;mask-image:linear-gradient(90deg,transparent,#000 45%,#000)}.visual-top,.visual-copy,.visual-footer{position:relative;z-index:1}.visual-top{display:flex;align-items:center;gap:18px}.visual-top img{width:148px;max-height:60px;object-fit:contain;object-position:left center;filter:brightness(0) invert(1)}.visual-top span,.visual-footer,.eyebrow,.form-kicker{font-size:10px;font-weight:700;letter-spacing:2px}.visual-top span{color:#9bb4d2;border-left:1px solid #ffffff40;padding-left:18px}.visual-copy{max-width:550px;margin:50px 0}.eyebrow{display:flex;align-items:center;gap:10px;color:#77dfeb}.eyebrow i{font-size:7px;text-shadow:0 0 12px #57d9e8}.visual-copy h1{margin:25px 0 18px;font:800 clamp(40px,5vw,68px)/1.08 'Manrope',sans-serif;letter-spacing:-3px}.visual-copy h1 span{color:#68d8ed}.visual-copy p{max-width:430px;color:#b5c4d8;font-size:16px;line-height:1.8}.visual-footer{display:flex;gap:12px;color:#8ea5bf;font-size:9px}.visual-orbit{position:absolute;border:1px solid #7fd8fc16;border-radius:50%;width:430px;height:430px;right:-90px;top:26%;box-shadow:0 0 70px #1882ff12,inset 0 0 70px #1882ff12}.orbit-two{width:300px;height:300px;right:-26px;top:34%;border-color:#7fd8fc20}.login-panel{display:flex;flex-direction:column;justify-content:center;align-items:center;padding:48px 32px;background:radial-gradient(ellipse at 50% 15%,#fff,#f5f7fb 70%)}.form-wrap{width:min(100%,390px)}.form-kicker{color:#3880ef;font-size:10px}.form-wrap h2{font:800 30px/1.3 'Manrope',sans-serif;letter-spacing:-1px;margin:11px 0 7px}.form-intro{color:var(--muted);font-size:14px;margin:0 0 31px}.form-wrap label{display:block;font-weight:700;font-size:12px;margin:18px 0 8px}.field{height:52px;display:flex;align-items:center;gap:12px;padding:0 15px;border:1px solid #dce3ed;border-radius:12px;background:#fff;transition:.2s}.field:focus-within{border-color:#4387f5;box-shadow:0 0 0 4px #4387f51a}.field>i{color:#8795aa;font-size:14px}.field input{width:100%;border:0;outline:0;font:500 14px 'DM Sans';color:var(--ink);background:transparent}.field input::placeholder{color:#a7b1c0}.field button{border:0;background:none;color:#8290a5;padding:5px;cursor:pointer}.submit-button{position:relative;width:100%;height:53px;margin-top:25px;border:0;border-radius:12px;background:linear-gradient(105deg,#246ff0,#168ed1);color:white;font:700 14px 'DM Sans';box-shadow:0 10px 22px #2676e933;cursor:pointer;transition:.2s}.submit-button:hover{transform:translateY(-1px);box-shadow:0 13px 28px #2676e944}.submit-button>i{position:absolute;right:18px;top:20px}.submit-button .spinner{display:none;position:absolute;right:18px;top:17px;width:19px;height:19px;border:2px solid #ffffff65;border-top-color:#fff;border-radius:50%;animation:spin .7s linear infinite}.submit-button.is-loading .spinner{display:block}.submit-button.is-loading>i{display:none}.submit-button.is-loading{opacity:.85;pointer-events:none}@keyframes spin{to{transform:rotate(360deg)}}.secure-note{display:flex;justify-content:center;align-items:center;gap:9px;margin-top:24px;color:#7e8ba0;font-size:11px}.secure-note i{color:#35a98c}.login-alert{display:flex;align-items:center;gap:10px;padding:12px 14px;margin:-13px 0 17px;border-radius:10px;font-size:12px}.login-alert.error{background:#fff0f0;color:#b33340}.login-alert.success{background:#eafaf2;color:#16744d}.ajax-message{display:none;margin-top:13px;color:#b33340;font-size:12px}.login-panel footer{margin-top:45px;color:#9ba6b7;font-size:11px}.mobile-brand{display:none}.csrf-refresh{display:none}@media(max-width:900px){.login-shell{grid-template-columns:42% 58%}.login-visual{padding:34px 30px}.visual-copy h1{font-size:45px}.visual-top img{width:120px}}@media(max-width:650px){.login-shell{display:flex;min-height:100svh;background:#f7f9fc}.login-visual{display:none}.login-panel{width:100%;min-height:100svh;justify-content:flex-start;padding:35px 25px 24px;background:radial-gradient(ellipse at 50% 0,#eaf3ff,transparent 46%),#f7f9fc}.mobile-brand{display:block;margin:15px 0 55px}.mobile-brand img{width:155px;max-height:62px;object-fit:contain}.form-wrap{width:min(100%,400px)}.form-wrap h2{font-size:27px}.login-panel footer{margin-top:auto;padding-top:35px}.field{height:54px}}
        .visual-top img{filter:none}
        .login-visual::after{content:"";position:absolute;width:32rem;height:32rem;right:-8rem;top:21%;border-radius:50%;background:radial-gradient(circle,rgba(36,143,255,.16),rgba(36,143,255,.045) 38%,transparent 70%);pointer-events:none;animation:visual-glow 9s ease-in-out infinite alternate}
        .visual-grid{animation:grid-drift 36s linear infinite}
        .visual-orbit{transform-origin:center;animation:orbit-drift 48s linear infinite}
        .orbit-two{animation-direction:reverse;animation-duration:38s}
        .visual-top{animation:login-enter .8s .06s both}
        .visual-copy{animation:login-enter .8s .2s both}
        .visual-footer{animation:login-enter .8s .38s both}
        .form-wrap{animation:login-enter .7s .12s both}
        .login-panel footer{animation:login-enter .7s .28s both}
        .visual-constellation{position:absolute;z-index:0;width:clamp(280px,37vw,460px);aspect-ratio:1;right:clamp(-95px,3vw,45px);top:50%;transform:translateY(-50%);display:grid;place-items:center;pointer-events:none;opacity:.8}
        .constellation-ring{position:absolute;border:1px solid rgba(115,208,255,.14);border-radius:50%;inset:2%;animation:ring-breathe 6s ease-in-out infinite}
        .ring-inner{inset:17%;border-style:dashed;border-color:rgba(115,208,255,.16);animation-delay:-3s}
        .constellation-core{width:92px;height:92px;display:grid;place-items:center;border-radius:28px;color:#d8f7ff;background:linear-gradient(145deg,rgba(35,139,234,.34),rgba(9,40,76,.74));border:1px solid rgba(133,222,255,.3);box-shadow:0 0 42px rgba(41,162,255,.23),inset 0 0 24px rgba(255,255,255,.06);animation:core-float 5s ease-in-out infinite}
        .constellation-core i{font-size:27px;text-shadow:0 0 20px rgba(104,216,237,.8)}
        .constellation-node{position:absolute;width:44px;height:44px;display:grid;place-items:center;border-radius:14px;color:#bceeff;background:rgba(7,30,58,.68);border:1px solid rgba(134,208,255,.24);box-shadow:0 8px 24px rgba(0,0,0,.13);animation:node-float 4.2s ease-in-out infinite}
        .constellation-node i{font-size:15px}
        .node-one{top:13%;right:18%;animation-delay:-.8s}.node-two{bottom:18%;left:12%;animation-delay:-2.3s}.node-three{bottom:19%;right:9%;animation-delay:-1.5s}
        @keyframes login-enter{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:translateY(0)}}
        @keyframes visual-glow{from{opacity:.55;transform:scale(.94)}to{opacity:1;transform:scale(1.06)}}
        @keyframes grid-drift{from{background-position:0 0}to{background-position:54px 54px}}
        @keyframes orbit-drift{from{rotate:0deg}to{rotate:360deg}}
        @keyframes ring-breathe{0%,100%{transform:scale(.98);opacity:.65}50%{transform:scale(1.025);opacity:1}}
        @keyframes core-float{0%,100%{transform:translateY(0) rotate(-3deg)}50%{transform:translateY(-9px) rotate(2deg)}}
        @keyframes node-float{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}
        @media(max-width:900px){.visual-constellation{right:-110px;opacity:.55}.constellation-core{width:72px;height:72px}.constellation-node{width:38px;height:38px}}
        @media(max-width:650px){.visual-constellation{display:none}}
        @media(prefers-reduced-motion:reduce){.visual-grid,.visual-orbit,.orbit-two,.visual-top,.visual-copy,.visual-footer,.form-wrap,.login-panel footer,.login-visual::after,.constellation-ring,.constellation-core,.constellation-node{animation:none!important;transition:none!important}}
    </style>
</head>
